// Service registrations
builder.Services.AddScoped<AppDbContext>(); // Per-request DB context
builder.Services.AddTransient<IEmailSender, EmailSender>(); // New per operation
builder.Services.AddSingleton<ICacheService, MemoryCacheService>(); // Shared cache

// Example: DbContext MUST be scoped
public class ProductRepository(AppDbContext db) { /* uses db */ }

// Example: Email sender can be transient (stateless)
public class EmailSender : IEmailSender { /* stateless */ }

// Example: Cache can be singleton (thread-safe)
public class MemoryCacheService : ICacheService { /* thread-safe */ }

// Demo service showing lifetime behavior
public class LifetimeDemoService(
    TransientService _transient,
    ScopedService _scoped,
    SingletonService _singleton)
{
    public Guid GetIds() => new(_transient.Id, _scoped.Id, _singleton.Id);
    // Transient: new instance each time
    // Scoped: same within request
    // Singleton: same across app
}
